              && block_token.key().block_size - size_of::<Node>() >= 0
              && padding.is_range(
                  block_start(block_token.key()),
                  block_token.key().block_size as int)
              && padding.provenance() == page_id.segment_id.provenance
              && block_token.instance_id() == instance.id()
